function search(query, limit) {
    if (!query || query.trim() === '') {
        return limit ? emojis.slice(0, limit) : emojis;
    }
    var q = query.toLowerCase().trim();
    var words = q.split(/\s+/).filter(function(w) { return w.length > 0; });
    var results = [];
    var max = limit || 120;

    for (var i = 0; i < emojis.length; i++) {
        var e = emojis[i];
        var nameLower = e.name.toLowerCase();
        var matchScore = 0;
        var allMatched = true;

        for (var w = 0; w < words.length; w++) {
            var word = words[w];
            var wordMatched = false;

            if (e.emoji === word) {
                matchScore += 10000;
                wordMatched = true;
            } else if (nameLower === word) {
                matchScore += 5000;
                wordMatched = true;
            } else if (nameLower.startsWith(word)) {
                matchScore += 3000;
                wordMatched = true;
            } else if (nameLower.indexOf(word) !== -1) {
                matchScore += 1500;
                wordMatched = true;
            } else {
                for (var k = 0; k < e.keywords.length; k++) {
                    var kw = e.keywords[k];
                    if (kw === word) {
                        matchScore += 2000;
                        wordMatched = true;
                        break;
                    } else if (kw.startsWith(word)) {
                        matchScore += 1000;
                        wordMatched = true;
                        break;
                    } else if (kw.indexOf(word) !== -1) {
                        matchScore += 400;
                        wordMatched = true;
                        break;
                    }
                }
            }

            if (!wordMatched) {
                allMatched = false;
                break;
            }
        }

        if (allMatched) {
            results.push({
                emoji: e.emoji,
                name: e.name,
                category: e.category,
                keywords: e.keywords,
                score: matchScore
            });
        }
    }

    results.sort(function(a, b) {
        if (a.score !== b.score) {
            return b.score - a.score;
        }
        return a.name.localeCompare(b.name);
    });

    return results.slice(0, max);
}
